    // 2. Trigger n8n for heavy tasks (async, external)
    ngt_trigger_n8n_workflow('session.completed', [
        'session_id' => $session_id,
        'tutor_id' => get_post_meta($session_id, '_amelia_employee_id', true),
        'student_id' => get_post_meta($session_id, '_amelia_customer_id', true)
    ]);

    // 3. Lightweight FluentCRM update (if needed)
    if (class_exists('FluentCRM\App\Api\Handlers\ContactHandler')) {
        // Update contact meta only - no email sends here
        fluentcrm_update_contact_meta($student_id, 'last_session_date', current_time('mysql'));
