// 4. Encrypt sensitive fields (bank accounts)
function ngt_encrypt_bank_data($data) {
    $key = defined('NGT_ENCRYPTION_KEY') ? NGT_ENCRYPTION_KEY : wp_salt('auth');
    return openssl_encrypt($data, 'AES-256-CBC', $key, 0, substr($key, 0, 16));
}
```

### API Security Middleware
```php
// All custom endpoints require Bearer token + rate limiting
function ngt_api_auth_check($request) {
    $token = $request->get_header('Authorization');
    if (!$token || !ngt_validate_bearer_token($token)) {
        return new WP_Error('unauthorized', 'Invalid token', ['status' => 401]);
    }

    // Rate limit: 60 requests/hour per user
    $user_id = get_current_user_id();
    if (!ngt_rate_limit($user_id, $request->get_route(), 60, 3600)) {
        return new WP_Error('rate_limited', 'Too many requests', ['status' => 429]);
    }

    return true;
}
```

