## 🌐 3. n8n Webhook Receiver with HMAC Security

### 📄 `inc/n8n-webhook-receiver.php`
```php
<?php
/**
 * n8n Webhook Receiver Endpoint
 * AI_AGENT: REST route at /wp-json/ngt/v1/webhooks/n8n with HMAC-SHA256 verification.
 */

if ( ! defined( 'ABSPATH' ) ) exit;

add_action( 'rest_api_init', 'ngt_register_n8n_webhook_route' );

function ngt_register_n8n_webhook_route() {
    register_rest_route( 'ngt/v1', '/webhooks/n8n', [
        'methods' => 'POST',
        'callback' => 'ngt_handle_n8n_webhook',
        'permission_callback' => '__return_true', // Signature verified internally
    ]);
}

function ngt_handle_n8n_webhook( WP_REST_Request $request ) {
    $secret = defined( 'NGT_N8N_WEBHOOK_SECRET' ) ? NGT_N8N_WEBHOOK_SECRET : '';
    if ( empty( $secret ) ) {
        return new WP_REST_Response( [ 'status' => 'error', 'message' => 'Missing webhook secret' ], 500 );
    }

    $raw_body = $request->get_body();
    $signature = $request->get_header( 'X-N8N-Signature' );
    $timestamp = intval( $request->get_header( 'X-N8N-Timestamp' ) );

    // 1. HMAC verification
    $expected = hash_hmac( 'sha256', $raw_body, $secret );
    if ( ! $signature || ! hash_equals( $expected, $signature ) ) {
        error_log( '[NGT-n8n] Invalid HMAC signature from n8n.' );
        return new WP_REST_Response( [ 'status' => 'error', 'message' => 'Unauthorized' ], 401 );
    }

    // 2. Replay attack protection (5-minute window)
    if ( abs( time() - $timestamp ) > 300 ) {
        return new WP_REST_Response( [ 'status' => 'error', 'message' => 'Expired timestamp' ], 410 );
    }

    // 3. Parse & route
    $payload = json_decode( $raw_body, true );
    if ( ! $payload || ! isset( $payload['event'] ) ) {
        return new WP_REST_Response( [ 'status' => 'error', 'message' => 'Invalid payload' ], 400 );
    }

    // 4. Dispatch to internal handlers
    switch ( $payload['event'] ) {
        case 'payment.completed':
            ngt_sync_payment_from_n8n( $payload['data'] );
            break;
        case 'session.completed':
            ngt_sync_session_from_n8n( $payload['data'] );
            break;
        case 'payout.processed':
            ngt_sync_payout_from_n8n( $payload['data'] );
            break;
        default:
            error_log( "[NGT-n8n] Unhandled event: {$payload['event']}" );
    }

    // Log successful receipt
    error_log( "[NGT-n8n] Webhook received: {$payload['event']}" );
    return new WP_REST_Response( [ 'status' => 'success', 'received_at' => current_time( 'mysql' ) ], 200 );
}

// AI_AGENT: Placeholder sync functions (expand per your architecture)
