## 🔐 Secure API Implementation (Bearer Token + HMAC)

### Middleware: `inc/rest-auth.php`
```php
<?php
// AI_AGENT: Secure API authentication layer

add_action('rest_api_init', 'ngt_register_auth_routes');

function ngt_register_auth_routes() {
    register_rest_route('ngt/v1', '/auth/token', [
        'methods' => 'POST',
        'callback' => 'ngt_generate_bearer_token',
        'permission_callback' => '__return_true'
    ]);
}

function ngt_generate_bearer_token(WP_REST_Request $request) {
    $email = sanitize_email($request->get_param('email'));
    $password = $request->get_param('password');

    $user = wp_authenticate($email, $password);
    if (is_wp_error($user)) {
        return new WP_Error('auth_failed', 'Invalid credentials', ['status' => 401]);
    }

    // Generate token (expires in 24h)
    $token = wp_generate_password(64, false);
    $expires = time() + DAY_IN_SECONDS;

    // Store in custom table (not user meta for security)
    global $wpdb;
    $wpdb->insert($wpdb->prefix . 'ngt_api_tokens', [
        'user_id' => $user->ID,
        'token' => wp_hash($token),
        'expires_at' => date('Y-m-d H:i:s', $expires),
        'created_at' => current_time('mysql')
    ]);

    return [
        'token' => $token,
        'expires_in' => DAY_IN_SECONDS,
        'user' => [
            'id' => $user->ID,
            'role' => ngt_get_user_role($user->ID),
            'permissions' => ngt_get_user_permissions($user->ID)
        ]
    ];
}

// Middleware for protected endpoints
function ngt_require_auth($request, $required_role = null) {
    $token = $request->get_header('Authorization');
    if (!$token || strpos($token, 'Bearer ') !== 0) {
        return new WP_Error('unauthorized', 'Missing or invalid token', ['status' => 401]);
    }

    $token = substr($token, 7); // Remove "Bearer "
    global $wpdb;
    $record = $wpdb->get_row($wpdb->prepare(
        "SELECT user_id, expires_at FROM {$wpdb->prefix}ngt_api_tokens WHERE token = %s",
        wp_hash($token)
    ));

    if (!$record || strtotime($record->expires_at) < time()) {
        return new WP_Error('token_expired', 'Token expired', ['status' => 401]);
    }

    $user = get_userdata($record->user_id);
    if (!$user) {
        return new WP_Error('user_not_found', 'User not found', ['status' => 404]);
    }

    // RBAC check
    if ($required_role && !user_can($user, $required_role)) {
        return new WP_Error('forbidden', 'Insufficient permissions', ['status' => 403]);
    }

    return $user;
}
```

