### API Security Middleware
```php
// Rate limiting + IP blocking
function ngt_rate_limit($user_id, $endpoint, $limit = 60, $window = 3600) {
    $key = "ngt_rate_{$user_id}_{$endpoint}";
    $count = (int) get_transient($key);
    if ($count >= $limit) {
        // Block IP for 1 hour if abuse detected
        if ($count > $limit * 2) {
            ngt_block_ip($_SERVER['REMOTE_ADDR'], 3600);
        }
        return false;
    }
    set_transient($key, $count + 1, $window);
    return true;
}
```

