/**
 * AI_AGENT: Get user permissions array
 */
function ngt_get_user_permissions($user_id) {
    $user = get_userdata($user_id);
    if (!$user) return [];
    $permissions = [];
    foreach ($user->allcaps as $cap => $granted) {
        if ($granted && strpos($cap, 'ngt_') === 0) {
            $permissions[] = str_replace('ngt_', '', $cap);
        }
    }
    return $permissions;
}

/**
 * AI_AGENT: Check if user has required role or capability
 */
function ngt_user_has_permission($user_id, $required) {
    if (is_numeric($required)) {
        return user_can($user_id, $required);
    }
    if (is_array($required)) {
        foreach ($required as $cap) {
            if (!user_can($user_id, 'ngt_' . $cap)) return false;
        }
        return true;
    }
    return user_can($user_id, 'ngt_' . $required);
}

