/**
 * AI_AGENT: Encrypt sensitive data (bank accounts)
 */
function ngt_encrypt_data($plaintext) {
    $key = defined('NGT_ENCRYPTION_KEY') ? NGT_ENCRYPTION_KEY : wp_salt('auth');
    $iv = openssl_random_pseudo_bytes(16);
    $ciphertext = openssl_encrypt($plaintext, 'AES-256-CBC', $key, 0, $iv);
    return base64_encode($iv . $ciphertext);
}

function ngt_decrypt_data($ciphertext) {
    $key = defined('NGT_ENCRYPTION_KEY') ? NGT_ENCRYPTION_KEY : wp_salt('auth');
    $decoded = base64_decode($ciphertext);
    $iv = substr($decoded, 0, 16);
    $encrypted = substr($decoded, 16);
    return openssl_decrypt($encrypted, 'AES-256-CBC', $key, 0, $iv);
}

/**
 * AI_AGENT: Sanitize all inputs (defense in depth)
 */
function ngt_sanitize_array($data) {
    if (!is_array($data)) return sanitize_text_field($data);
    foreach ($data as $key => $value) {
        $data[$key] = is_array($value) ? ngt_sanitize_array($value) : sanitize_text_field($value);
 sp   }
    return $data;
}

// ============================================================================
// 🤖 N8N WEBHOOK TRIGGER HELPER
// ============================================================================

/**
 * AI_AGENT: Async trigger n8n webhook (non-blocking)
 */
function ngt_trigger_n8n_webhook($event, $data) {
    if (!defined('NGT_N8N_WEBHOOK_URL') || !defined('NGT_N8N_WEBHOOK_SECRET')) return;

    $payload = json_encode(['event' => $event, 'data' => $data]);
    $signature = hash_hmac('sha256', $payload, NGT_N8N_WEBHOOK_SECRET);

    // Fire async via wp_remote_post with short timeout
    wp_remote_post(NGT_N8N_WEBHOOK_URL, [
        'headers' => [
            'Content-Type' => 'application/json',
            'X-N8N-Signature' => $signature,
            'X-N8N-Timestamp' => time()
        ],
        'body' => $payload,
        'timeout' => 2, // Non-blocking
        'blocking' => false
    ]);
}

