function Initialize-DirectoryStructure {
    param([string]$BasePath)

    Write-Host "📁 Creating directory structure at $BasePath" -ForegroundColor Cyan

    $directories = @(
        "$BasePath\wordpress\wp-content\themes\$($Config.ThemeName)\inc",
