function Write-File {
    param(
        [string]$Path,
        [string]$Content,
        [string]$Encoding = "UTF8"
    )

    $dir = Split-Path $Path -Parent
    if (!(Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }

    [System.IO.File]::WriteAllText($Path, $Content, [System.Text.Encoding]::$Encoding)
    Write-Host "  ✓ Generated: $(Split-Path $Path -Leaf)" -ForegroundColor Green
}

