            'ngt_submit_homework' => true]],
        'tutor' => ['display_name' => 'Tutor', 'capabilities' => [
            'read' => true, 'ngt_manage_availability' => true, 'ngt_view_own_earnings' => true,
            'ngt_upload_resources' => true, 'ngt_mark_session_complete' => true,
            'ngt_receive_payouts' => true]],
        'support' => ['display_name' => 'Support Agent', 'capabilities' => [
            'read' => true, 'ngt_view_tickets' => true, 'ngt_respond_to_users' => true,
            'ngt_escalate_issues' => true, 'ngt_view_logs' => true]],
        'admin' => ['display_name' => 'Administrator', 'capabilities' => [
            'manage_options' => true, 'ngt_manage_tutors' => true, 'ngt_process_payouts' => true,
            'ngt_view_all_reports' => true, 'ngt_manage_content' => true,
            'ngt_override_permissions' => true]]
    ];

    foreach ($roles as $role_slug => $role_data) {
        $role = get_role($role_slug);
        if (!$role) {
            $role = add_role($role_slug, $role_data['display_name'], $role_data['capabilities']);
        } else {
            foreach ($role_data['capabilities'] as $cap => $grant) {
                $role->add_cap($cap, $grant);
            }
        }
    }
}

function ngt_get_user_role($user_id) {
    $user = get_userdata($user_id);
    if (!$user) return 'subscriber';
    $roles = array_values($user->roles);
    return $roles[0] ?? 'subscriber';
}

function ngt_get_user_permissions($user_id) {
    $user = get_userdata($user_id);
    if (!$user) return [];
    $permissions = [];
    foreach ($user->allcaps as $cap => $granted) {
        if ($granted && strpos($cap, 'ngt_') === 0) {
            $permissions[] = str_replace('ngt_', '', $cap);
        }
    }
    return $permissions;
}

function ngt_user_has_permission($user_id, $required) {
    if (is_numeric($required)) return user_can($user_id, $required);
    if (is_array($required)) {
        foreach ($required as $cap) {
            if (!user_can($user_id, 'ngt_' . $cap)) return false;
        }
        return true;
    }
    return user_can($user_id, 'ngt_' . $required);
}

