function ngt_generate_bearer_token(WP_REST_Request $request) {
    $email = sanitize_email($request->get_param('email'));
    $password = $request->get_param('password');

    if (empty($email) || empty($password)) {
        return new WP_Error('missing_credentials', 'Email and password required', ['status' => 400]);
    }

    $user = wp_authenticate($email, $password);
    if (is_wp_error($user)) {
        error_log("[NGT-AUTH] Failed login attempt for: $email");
        return new WP_Error('auth_failed', 'Invalid credentials', ['status' => 401]);
    }

    $token = wp_generate_password(64, false);
    $expires = time() + NGT_API_TOKEN_EXPIRY;

    global $wpdb;
    $wpdb->insert($wpdb->prefix . 'ngt_api_tokens', [
        'user_id' => $user->ID,
        'token_hash' => wp_hash($token),
        'expires_at' => date('Y-m-d H:i:s', $expires),
        'created_at' => current_time('mysql')
    ], ['%d', '%s', '%s', '%s']);

    return [
        'token' => $token,
        'token_type' => 'Bearer',
        'expires_in' => NGT_API_TOKEN_EXPIRY,
        'user' => [
            'id' => $user->ID,
            'email' => $user->user_email,
            'role' => ngt_get_user_role($user->ID),
            'permissions' => ngt_get_user_permissions($user->ID),
            'profile' => [
                'first_name' => get_user_meta($user->ID, 'first_name', true),
                'last_name' => get_user_meta($user->ID, 'last_name', true),
                'verified' => (bool) get_user_meta($user->ID, '_ngt_verified', true),
            ]
        ]
    ];
}

function ngt_require_auth($request, $required_permission = null) {
    $auth_header = $request->get_header('Authorization');
    if (!$auth_header || strpos($auth_header, 'Bearer ') !== 0) {
        return new WP_Error('unauthorized', 'Missing or invalid Authorization header', ['status' => 401]);
    }

    $token = substr($auth_header, 7);
    global $wpdb;

    $record = $wpdb->get_row($wpdb->prepare(
        "SELECT user_id, expires_at FROM {$wpdb->prefix}ngt_api_tokens 
         WHERE token_hash = %s AND expires_at > NOW()",
        wp_hash($token)
    ));

    if (!$record) {
        return new WP_Error('token_invalid', 'Invalid or expired token', ['status' => 401]);
    }

    $user = get_userdata($record->user_id);
    if (!$user || !$user->exists()) {
        return new WP_Error('user_not_found', 'User not found', ['status' => 404]);
    }

    $wpdb->update($wpdb->prefix . 'ngt_api_tokens', 
        ['last_used' => current_time('mysql')], 
        ['id' => $record->id]
    );

    if ($required_permission && !ngt_user_has_permission($user->ID, $required_permission)) {
        error_log("[NGT-RBAC] User {$user->ID} denied access to: $required_permission");
        return new WP_Error('forbidden', 'Insufficient permissions', ['status' => 403]);
    }

    if (!ngt_rate_limit($user->ID, $request->get_route())) {
        return new WP_Error('rate_limited', 'Too many requests. Try again later.', ['status' => 429]);
    }

    return $user;
}

function ngt_rate_limit($user_id, $endpoint, $limit = NGT_RATE_LIMIT_MAX, $window = NGT_RATE_LIMIT_WINDOW) {
    $key = "ngt_rate_{$user_id}_" . md5($endpoint);
    $count = (int) get_transient($key);

    if ($count >= $limit) {
        error_log("[NGT-RATE] User $user_id exceeded limit on $endpoint");
        return false;
    }

    set_transient($key, $count + 1, $window);
    return true;
}

