// 💰 PAYFAST ITN HANDLER (SOUTH AFRICA)
// ============================================================================

function ngt_handle_payfast_itn(WP_REST_Request $request) {
    $raw_input = file_get_contents('php://input');
    parse_str($raw_input, $data);

    $passphrase = defined('NGT_PAYFAST_PASSPHRASE') ? NGT_PAYFAST_PASSPHRASE : '';
    if (!ngt_verify_payfast_signature($data, $passphrase)) {
        error_log('[NGT-PayFast] Invalid ITN signature. IP: ' . ($_SERVER['REMOTE_ADDR'] ?? 'unknown'));
        status_header(403);
        echo 'INVALID_SIGNATURE';
        exit;
    }

    $order_id = intval($data['order_id'] ?? 0);
    $pf_payment_id = sanitize_text_field($data['pf_payment_id'] ?? '');

    if (!$order_id || get_post_meta($order_id, '_ngt_payfast_processed', true)) {
        echo 'ALREADY_PROCESSED';
        exit;
    }

    $payment_status = strtoupper(sanitize_text_field($data['payment_status'] ?? ''));
    if ($payment_status !== 'COMPLETE') {
        echo 'IGNORED_STATUS_' . $payment_status;
        exit;
    }

    $order = wc_get_order($order_id);
    if ($order) {
        $order->update_status('completed', 'PayFast ITN confirmed');
        $order->add_meta_data('_ngt_payfast_processed', true);
        $order->add_meta_data('_ngt_payfast_pf_id', $pf_payment_id);
        $order->save();
    }

    ngt_record_earnings_from_order($order);

    ngt_trigger_n8n_webhook('payment.completed', [
        'order_id' => $order_id,
        'customer_id' => $order ? $order->get_customer_id() : null,
        'amount' => $order ? $order->get_total() : floatval($data['amount_gross'] ?? 0),
        'pf_payment_id' => $pf_payment_id,
        'items' => $order ? array_map(fn($item) => [
            'name' => $item->get_name(),
            'quantity' => $item->get_quantity(),
            'total' => $item->get_total()
        ], $order->get_items()) : []
    ]);

    error_log("[NGT-PayFast] ITN processed: Order #{$order_id}, PF ID: {$pf_payment_id}");
    echo 'OK';
    exit;
}

function ngt_verify_payfast_signature($data, $passphrase) {
    $computed = $data['signature'] ?? '';
    unset($data['signature']);
    ksort($data);
    $pf_string = http_build_query($data);
    $expected = md5($pf_string . $passphrase);
    return hash_equals($expected, $computed);
}

function ngt_record_earnings_from_order($order) {
    if (!$order) return;
    global $wpdb;
    $tutor_id = null;

    foreach ($order->get_items() as $item) {
        $product_id = $item->get_product_id();
        $tutor_id = get_post_meta($product_id, '_ngt_tutor_id', true) ?: $tutor_id;
    }

    if (!$tutor_id) return;

    $gross = $order->get_total();
    $platform_fee = $gross * NGT_PLATFORM_FEE;
    $net = $gross - $platform_fee;

    $wpdb->insert($wpdb->prefix . 'ngt_earnings', [
        'tutor_id' => $tutor_id, 'session_id' => 0, 'amount' => $gross,
        'platform_fee' => $platform_fee, 'penalties' => 0, 'bonuses' => 0,
        'net_amount' => $net, 'status' => 'pending',
        'created_at' => current_time('mysql'), 'updated_at' => current_time('mysql')
    ], ['%d', '%d', '%f', '%f', '%f', '%f', '%f', '%s', '%s', '%s']);
}

// ============================================================================
// 🌐 N8N WEBHOOK RECEIVER (HMAC-SHA256)
// ============================================================================

function ngt_handle_n8n_webhook(WP_REST_Request $request) {
    $secret = defined('NGT_N8N_WEBHOOK_SECRET') ? NGT_N8N_WEBHOOK_SECRET : '';
    if (empty($secret)) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Webhook secret not configured'], 500);
    }

    $raw_body = $request->get_body();
    $signature = $request->get_header('X-N8N-Signature');
    $timestamp = intval($request->get_header('X-N8N-Timestamp') ?? 0);

    $expected = hash_hmac('sha256', $raw_body, $secret);
    if (!$signature || !hash_equals($expected, $signature)) {
        error_log('[NGT-n8n] Invalid HMAC signature from n8n');
        return new WP_REST_Response(['status' => 'error', 'message' => 'Unauthorized'], 401);
    }

    if (abs(time() - $timestamp) > 300) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Expired timestamp'], 410);
    }

    $payload = json_decode($raw_body, true);
    if (!is_array($payload) || !isset($payload['event'])) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Invalid payload'], 400);
    }

    switch ($payload['event']) {
        case 'payment.completed': ngt_sync_payment_from_n8n($payload['data'] ?? []); break;
        case 'session.completed': ngt_sync_session_from_n8n($payload['data'] ?? []); break;
        case 'payout.processed': ngt_sync_payout_from_n8n($payload['data'] ?? []); break;
        case 'rating.submitted': ngt_sync_rating_from_n8n($payload['data'] ?? []); break;
        default:
            error_log("[NGT-n8n] Unhandled event: {$payload['event']}");
            return new WP_REST_Response(['status' => 'ignored', 'event' => $payload['event']], 200);
    }

    error_log("[NGT-n8n] Webhook processed: {$payload['event']}");
    return new WP_REST_Response(['status' => 'success', 'received_at' => current_time('mysql')], 200);
}

function ngt_sync_payment_from_n8n($data) {
    global $wpdb;
    $order_id = intval($data['order_id'] ?? 0);
    if (!$order_id || get_post_meta($order_id, '_ngt_n8n_synced', true)) return;

    update_post_meta($order_id, '_ngt_n8n_synced', true);
    update_post_meta($order_id, '_ngt_n8n_synced_at', current_time('mysql'));

    if (class_exists('FluentCRM\App\Models\Contact')) {
        $customer_id = intval($data['customer_id'] ?? 0);
        if ($customer_id) {
            $user = get_userdata($customer_id);
            if ($user) {
                $contact = \FluentCRM\App\Models\Contact::where('email', $user->user_email)->first();
                if ($contact) {
                    $contact->attachTags(['payment-verified']);
                    $contact->custom_fields['last_payment_date'] = current_time('mysql');
                    $contact->save();
                }
            }
        }
    }
}

function ngt_sync_session_from_n8n($data) {
    global $wpdb;
    $session_id = intval($data['session_id'] ?? 0);
    if (!$session_id) return;

    $wpdb->update($wpdb->prefix . 'ngt_session_logs',
        ['status' => 'completed', 'updated_at' => current_time('mysql')],
        ['session_id' => $session_id],
        ['%s', '%s'], ['%d']
    );

    $tutor_id = intval($data['tutor_id'] ?? 0);
    if ($tutor_id) ngt_calculate_and_record_earnings($session_id, $tutor_id);

    if (function_exists('automatorwp_trigger_event')) {
        automatorwp_trigger_event([
            'trigger' => 'ngt_session_completed',
            'user_id' => $tutor_id,
            'session_id' => $session_id
        ]);
    }
}

// ============================================================================
// 💰 EARNINGS CALCULATION ENGINE
// ============================================================================

function ngt_calculate_and_record_earnings($session_id, $tutor_id) {
    global $wpdb;
    $session = get_post($session_id);
    if (!$session) return;

    $rate = floatval(get_post_meta($session_id, '_ngt_session_rate', true) ?: 400);
    $gross = $rate;
    $platform_fee = $gross * NGT_PLATFORM_FEE;

    $penalties = 0;
    $attendance = get_post_meta($session_id, '_ngt_attendance_tutor', true);
    if ($attendance === 'absent') $penalties += $gross * 0.5;

    $bonuses = 0;
    $tutor_rating = floatval(get_user_meta($tutor_id, '_ngt_average_rating', true) ?: 0);
    if ($tutor_rating >= NGT_TOP_RATING_THRESHOLD) $bonuses += $gross * 0.05;

    $net = $gross - $platform_fee - $penalties + $bonuses;

    $wpdb->insert($wpdb->prefix . 'ngt_earnings', [
        'tutor_id' => $tutor_id, 'session_id' => $session_id, 'amount' => $gross,
        'platform_fee' => $platform_fee, 'penalties' => $penalties, 'bonuses' => $bonuses,
        'net_amount' => $net, 'status' => 'pending',
        'created_at' => current_time('mysql'), 'updated_at' => current_time('mysql')
    ], ['%d', '%d', '%f', '%f', '%f', '%f', '%f', '%s', '%s', '%s']);

    $current_earnings = floatval(get_user_meta($tutor_id, '_ngt_total_earned', true) ?: 0);
    update_user_meta($tutor_id, '_ngt_total_earned', $current_earnings + $net);

    return $net;
}

// ============================================================================
// ⭐ RATING SYSTEM & QUALITY CONTROL
// ============================================================================

function ngt_api_submit_rating(WP_REST_Request $request) {
    $user = ngt_require_auth($request, 'rate_tutor');
    if (is_wp_error($user)) return $user;

    $params = $request->get_json_params();
    $session_id = intval($params['session_id'] ?? 0);
    $rating = intval($params['rating'] ?? 0);
    $comment = sanitize_textarea_field($params['comment'] ?? '');

    if ($rating < 1 || $rating > 5) {
        return new WP_Error('invalid_rating', 'Rating must be 1-5', ['status' => 400]);
    }

    global $wpdb;
    $existing = $wpdb->get_var($wpdb->prepare(
        "SELECT id FROM {$wpdb->prefix}ngt_ratings 
         WHERE rater_id = %d AND session_id = %d AND rater_type = 'student'",
        $user->ID, $session_id
    ));

    if ($existing) {
        return new WP_Error('duplicate', 'Rating already submitted for this session', ['status' => 409]);
    }

    $tutor_id = intval(get_post_meta($session_id, '_ngt_tutor_id', true));
    if (!$tutor_id) {
        return new WP_Error('invalid_session', 'Tutor not found for session', ['status' => 404]);
    }

    $wpdb->insert($wpdb->prefix . 'ngt_ratings', [
        'rater_id' => $user->ID, 'rater_type' => 'student', 'target_id' => $tutor_id,
        'session_id' => $session_id, 'rating' => $rating, 'comment' => $comment,
        'created_at' => current_time('mysql'), 'updated_at' => current_time('mysql')
    ], ['%d', '%s', '%d', '%d', '%d', '%s', '%s', '%s']);

    ngt_update_tutor_average_rating($tutor_id);

    if ($rating < NGT_LOW_RATING_THRESHOLD) {
        ngt_trigger_quality_alert($tutor_id, $rating, $comment);
    }

    ngt_trigger_n8n_webhook('rating.submitted', [
        'session_id' => $session_id, 'tutor_id' => $tutor_id,
        'student_id' => $user->ID, 'rating' => $rating, 'comment' => $comment
    ]);

    return [
        'id' => $wpdb->insert_id,
        'created_at' => current_time('mysql'),
        'tutor_average_rating' => get_user_meta($tutor_id, '_ngt_average_rating', true)
    ];
}

function ngt_update_tutor_average_rating($tutor_id) {
    global $wpdb;
    $avg = $wpdb->get_var($wpdb->prepare(
        "SELECT AVG(rating) FROM {$wpdb->prefix}ngt_ratings 
         WHERE target_id = %d AND rater_type = 'student'",
        $tutor_id
    ));
    $avg = $avg ? round(floatval($avg), 2) : 0;
    update_user_meta($tutor_id, '_ngt_average_rating', $avg);

    $review_count = intval($wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM {$wpdb->prefix}ngt_ratings 
         WHERE target_id = %d AND rater_type = 'student'",
        $tutor_id
    )));

    if ($review_count >= NGT_REVIEW_COUNT_BADGE && !get_user_meta($tutor_id, '_ngt_badge_popular', true)) {
        update_user_meta($tutor_id, '_ngt_badge_popular', time());
        if (function_exists('automatorwp_trigger_event')) {
            automatorwp_trigger_event([
                'trigger' => 'ngt_badge_awarded',
                'user_id' => $tutor_id,
                'badge' => 'popular_tutor'
            ]);
        }
    }
    return $avg;
}

function ngt_trigger_quality_alert($tutor_id, $rating, $comment) {
    if (function_exists('automatorwp_trigger_event')) {
        automatorwp_trigger_event([
            'trigger' => 'ngt_quality_alert',
            'user_id' => $tutor_id,
            'rating' => $rating,
            'comment' => $comment
        ]);
    }

    $admin_email = get_option('admin_email');
    wp_mail($admin_email, '[NGT Alert] Low Rating Received', 
        "Tutor #$tutor_id received a {$rating}/5 rating.\nComment: {$comment}\nReview required.");
}

