### 🔗 Required WordPress Endpoint (Add to `functions-enhanced.php`)
```php
add_action('rest_api_init', function() {
    register_rest_route('ngt/v1', '/zoom/register-recording', [
        'methods' => 'POST',
        'callback' => 'ngt_register_zoom_recording',
        'permission_callback' => fn($r) => strpos($r->get_header('Authorization'), 'Bearer ') === 0
    ]);
});

function ngt_register_zoom_recording(WP_REST_Request $request) {
    $params = $request->get_json_params();
    global $wpdb;

    // Find session by Zoom UUID
    $session = $wpdb->get_row($wpdb->prepare(
        "SELECT id FROM {$wpdb->prefix}ngt_session_logs WHERE zoom_uuid = %s",
        $params['zoom_uuid']
    ));

    if (!$session) return new WP_Error('not_found', 'Session not found', ['status' => 404]);

    // Update recording URL & schedule POPIA deletion
    $wpdb->update($wpdb->prefix . 'ngt_session_logs',
        ['recording_url' => esc_url_raw($params['recording_url']), 'updated_at' => current_time('mysql')],
        ['id' => $session->id]
    );

    // Schedule single event for POPIA auto-delete (30 days)
    wp_schedule_single_event(strtotime('+30 days'), 'ngt_delete_zoom_recording', [$session->id]);

    return ['status' => 'success', 'session_id' => $session->id];
}

add_action('ngt_delete_zoom_recording', function($session_id) {
    global $wpdb;
    $wpdb->update($wpdb->prefix . 'ngt_session_logs',
        ['recording_url' => null, 'updated_at' => current_time('mysql')],
        ['id' => $session_id]
    );
    error_log("[NGT-Zoom] POPIA auto-deleted recording for session $session_id");
});
```

