### 🔹 Step 2: PHP Sync Hook (Add to `functions-enhanced.php`)
```php
<?php
/**
 * FluentCRM POPIA Consent Sync
 * Syncs consent from WooCommerce, Registration, and Custom Forms
 * POPIA §11: Explicit, informed, unambiguous consent
 */

add_action('woocommerce_checkout_create_order', 'ngt_sync_popia_to_fluentcrm', 10, 2);
function ngt_sync_popia_to_fluentcrm($order, $data) {
    if (empty($_POST['ngt_popia_consent']) || $_POST['ngt_popia_consent'] !== '1') return;

    $user_id = $order->get_customer_id();
    if (!$user_id) return;

    $user = get_userdata($user_id);
    if (!$user) return;

    $consent_audit = [
        'given' => true,
        'timestamp' => current_time('mysql'),
        'ip' => WC_Geolocation::get_ip_address(),
        'ua' => wc_get_user_agent(),
        'version' => '1.2',
        'source' => 'woocommerce_checkout'
    ];

    // Save to WordPress
    update_user_meta($user_id, '_ngt_popia_consent', $consent_audit);

    // Sync to FluentCRM
    if (class_exists('FluentCRM\App\Models\Contact')) {
        $contact = \FluentCRM\App\Models\Contact::where('email', $user->user_email)->first();
        if ($contact) {
            $contact->custom_fields['popia_consent_given'] = true;
            $contact->custom_fields['popia_consent_date'] = $consent_audit['timestamp'];
            $contact->custom_fields['popia_consent_ip'] = $consent_audit['ip'];
            $contact->custom_fields['popia_consent_version'] = $consent_audit['version'];
            $contact->save();

            // Trigger segment/tag automation
            $contact->attachTags(['POPIA Consent']);
            $contact->addToLists(['Active Customers']);
        }
    }
}

add_action('user_register', 'ngt_sync_registration_popia', 10, 1);
function ngt_sync_registration_popia($user_id) {
    if (empty($_POST['ngt_popia_consent']) || $_POST['ngt_popia_consent'] !== '1') return;

    $user = get_userdata($user_id);
    $consent = ['given'=>true, 'timestamp'=>current_time('mysql'), 'ip'=>$_SERVER['REMOTE_ADDR'], 'source'=>'registration'];
    update_user_meta($user_id, '_ngt_popia_consent', $consent);

    // Sync to FluentCRM
    if (class_exists('FluentCRM\App\Models\Contact')) {
        $contact = \FluentCRM\App\Models\Contact::where('email', $user->user_email)->first();
        if ($contact) {
            $contact->custom_fields['popia_consent_given'] = true;
            $contact->custom_fields['popia_consent_date'] = $consent['timestamp'];
            $contact->save();
        }
    }
}
