    if (!hash_equals(hash_hmac('sha256', json_encode($payload), $secret), $signature)) {
        return new WP_Error('invalid_signature', 'Unauthorized', ['status' => 401]);
    }

    // Route by event type
    switch ($payload['event'] ?? '') {
        case 'payment.completed':
            ngt_process_payment_completed($payload['data']);
            break;
        case 'session.completed':
            ngt_process_session_completed($payload['data']);
            break;
        case 'payout.processed':
            ngt_log_payout_confirmation($payload['data']);
            break;
    }

    return ['status' => 'received'];
}
