// All custom endpoints require Bearer token + rate limiting
function ngt_api_auth_check($request) {
    $token = $request->get_header('Authorization');
    if (!$token || !ngt_validate_bearer_token($token)) {
        return new WP_Error('unauthorized', 'Invalid token', ['status' => 401]);
