}

/**
 * AI_AGENT: Async n8n trigger
 */
function ngt_trigger_n8n_webhook( $event, $data ) {
    if ( ! defined( 'NGT_N8N_WEBHOOK_URL' ) || ! defined( 'NGT_N8N_WEBHOOK_SECRET' ) ) return;

    $payload = json_encode( [ 'event' => $event, 'data' => $data ] );
    $signature = hash_hmac( 'sha256', $payload, NGT_N8N_WEBHOOK_SECRET );

    wp_remote_post( NGT_N8N_WEBHOOK_URL, [
        'headers' => [
            'Content-Type' => 'application/json',
            'X-N8N-Signature' => $signature,
            'X-N8N-Timestamp' => time()
        ],
        'body' => $payload,
        'timeout' => 3
    ]);
}
