name: 🔄 NextGen Tutors CI/CD
on:
  push:
    branches: [main, develop]
  pull_request:
    branches: [main]

env:
  PHP_VERSION: 8.1
  WP_VERSION: 6.5
  STAGING_HOST: ${{ secrets.STAGING_SSH_HOST }}
  STAGING_USER: ${{ secrets.STAGING_SSH_USER }}
