jobs:
  lint-test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Setup PHP
        uses: shivammathur/setup-php@v2
        with:
          php-version: ${{ env.PHP_VERSION }}
          extensions: mbstring, intl, xml, mysql
      - name: Install deps
        run: composer install --no-interaction --prefer-dist
      - name: PHPStan Analysis
        run: vendor/bin/phpstan analyse inc/ templates/ --level=5
      - name: PHPUnit Tests
        run: vendor/bin/phpunit --log-junit report.xml

  security-scan:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Trivy Security Scan
        uses: aquasecurity/trivy-action@master
        with:
          scan-type: 'fs'
          format: 'sarif'
          output: 'trivy-results.sarif'
      - name: Upload SARIF
        uses: github/codeql-action/upload-sarif@v3
        with:
          sarif_file: 'trivy-results.sarif'

  deploy-staging:
    needs: [lint-test, security-scan]
    if: github.ref == 'refs/heads/main'
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Setup SSH Key
        run: |
          mkdir -p ~/.ssh
          echo "${{ secrets.STAGING_SSH_KEY }}" > ~/.ssh/id_ed25519
          chmod 600 ~/.ssh/id_ed25519
          ssh-keyscan -H ${{ env.STAGING_HOST }} >> ~/.ssh/known_hosts
      - name: Sync Files via Rsync
        run: |
          rsync -avz --delete --exclude='.git' --exclude='vendor/' --exclude='node_modules/' --exclude='.env' ./ ${{ env.STAGING_USER }}@${{ env.STAGING_HOST }}:${{ env.STAGING_PATH }}
      - name: WP-CLI Post-Deploy
        run: |
          ssh ${{ env.STAGING_USER }}@${{ env.STAGING_HOST }} "
            cd ${{ env.STAGING_PATH }}
            wp theme activate nextgen-tutors --skip-plugins
            wp cache flush
            wp cron test || echo 'WP-Cron test skipped (shared hosting)'
            curl -s https://${{ secrets.STAGING_DOMAIN }}/wp-json/ >/dev/null
          "
      - name: Deployment Complete
        run: echo "✅ Staging deployed to ${{ secrets.STAGING_DOMAIN }}"
```
