// ============================================================================
// 💰 PAYFAST ITN HANDLER (SOUTH AFRICA)
// ============================================================================

/**
 * AI_AGENT: PayFast Instant Transaction Notification handler
 * Verifies signature, prevents idempotency, records earnings, triggers n8n
 */
function ngt_handle_payfast_itn(WP_REST_Request $request) {
    // Raw payload for signature verification
    $raw_input = file_get_contents('php://input');
    parse_str($raw_input, $data);

    // 1. Signature verification (PayFast spec)
    $passphrase = defined('NGT_PAYFAST_PASSPHRASE') ? NGT_PAYFAST_PASSPHRASE : '';
    if (!ngt_verify_payfast_signature($data, $passphrase)) {
        error_log('[NGT-PayFast] Invalid ITN signature. IP: ' . ($_SERVER['REMOTE_ADDR'] ?? 'unknown'));
        status_header(403);
        echo 'INVALID_SIGNATURE';
        exit;
    }

    // 2. Idempotency check
    $order_id = intval($data['order_id'] ?? 0);
    $pf_payment_id = sanitize_text_field($data['pf_payment_id'] ?? '');

    if (!$order_id || get_post_meta($order_id, '_ngt_payfast_processed', true)) {
        echo 'ALREADY_PROCESSED';
        exit;
    }

    // 3. Process only COMPLETE status
    $payment_status = strtoupper(sanitize_text_field($data['payment_status'] ?? ''));
    if ($payment_status !== 'COMPLETE') {
        echo 'IGNORED_STATUS_' . $payment_status;
        exit;
    }

    // 4. Update WooCommerce order
    $order = wc_get_order($order_id);
    if ($order) {
        $order->update_status('completed', 'PayFast ITN confirmed');
        $order->add_meta_data('_ngt_payfast_processed', true);
        $order->add_meta_data('_ngt_payfast_pf_id', $pf_payment_id);
        $order->save();
    }

    // 5. Record earnings in custom table
    ngt_record_earnings_from_order($order);

    // 6. Trigger n8n webhook for async processing
    ngt_trigger_n8n_webhook('payment.completed', [
        'order_id' => $order_id,
        'customer_id' => $order ? $order->get_customer_id() : null,
        'amount' => $order ? $order->get_total() : floatval($data['amount_gross'] ?? 0),
        'pf_payment_id' => $pf_payment_id,
        'items' => $order ? array_map(function($item) {
            return [
                'name' => $item->get_name(),
                'quantity' => $item->get_quantity(),
                'total' => $item->get_total()
            ];
        }, $order->get_items()) : []
    ]);

    // 7. Log for audit
    error_log("[NGT-PayFast] ITN processed: Order #{$order_id}, PF ID: {$pf_payment_id}");
    echo 'OK';
    exit;
}

/**
 * AI_AGENT: PayFast signature validation per official spec
 */
function ngt_verify_payfast_signature($data, $passphrase) {
    $computed = $data['signature'] ?? '';
    unset($data['signature']);

    ksort($data);
    $pf_string = http_build_query($data);
    $expected = md5($pf_string . $passphrase);

    return hash_equals($expected, $computed);
}

/**
 * AI_AGENT: Record earnings from WooCommerce order
 */
function ngt_record_earnings_from_order($order) {
    if (!$order) return;

    global $wpdb;
    $tutor_id = null;

    // Extract tutor from order items (Amelia booking or custom product)
    foreach ($order->get_items() as $item) {
        $product_id = $item->get_product_id();
        $tutor_id = get_post_meta($product_id, '_ngt_tutor_id', true) ?: $tutor_id;
    }

    if (!$tutor_id) return;

    $gross = $order->get_total();
    $platform_fee = $gross * NGT_PLATFORM_FEE;
    $net = $gross - $platform_fee;

    $wpdb->insert($wpdb->prefix . 'ngt_earnings', [
        'tutor_id' => $tutor_id,
        'session_id' => 0, // Link to Amelia booking if available
        'amount' => $gross,
        'platform_fee' => $platform_fee,
        'penalties' => 0,
        'bonuses' => 0,
        'net_amount' => $net,
        'status' => 'pending',
        'created_at' => current_time('mysql'),
        'updated_at' => current_time('mysql')
    ], ['%d', '%d', '%f', '%f', '%f', '%f', '%f', '%s', '%s', '%s']);
}

// ============================================================================
// 🌐 N8N WEBHOOK RECEIVER (HMAC-SHA256)
// ============================================================================

/**
 * AI_AGENT: Secure webhook receiver for n8n automation
 * Verifies HMAC signature, timestamp, routes to internal handlers
 */
function ngt_handle_n8n_webhook(WP_REST_Request $request) {
    $secret = defined('NGT_N8N_WEBHOOK_SECRET') ? NGT_N8N_WEBHOOK_SECRET : '';
    if (empty($secret)) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Webhook secret not configured'], 500);
    }

    $raw_body = $request->get_body();
    $signature = $request->get_header('X-N8N-Signature');
    $timestamp = intval($request->get_header('X-N8N-Timestamp') ?? 0);

    // 1. HMAC verification
    $expected = hash_hmac('sha256', $raw_body, $secret);
    if (!$signature || !hash_equals($expected, $signature)) {
        error_log('[NGT-n8n] Invalid HMAC signature from n8n');
        return new WP_REST_Response(['status' => 'error', 'message' => 'Unauthorized'], 401);
    }

    // 2. Replay attack protection (5-minute window)
    if (abs(time() - $timestamp) > 300) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Expired timestamp'], 410);
    }

    // 3. Parse payload
    $payload = json_decode($raw_body, true);
    if (!is_array($payload) || !isset($payload['event'])) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Invalid payload'], 400);
    }

    // 4. Route by event type
    switch ($payload['event']) {
        case 'payment.completed':
            ngt_sync_payment_from_n8n($payload['data'] ?? []);
            break;
        case 'session.completed':
            ngt_sync_session_from_n8n($payload['data'] ?? []);
            break;
        case 'payout.processed':
            ngt_sync_payout_from_n8n($payload['data'] ?? []);
            break;
        case 'rating.submitted':
            ngt_sync_rating_from_n8n($payload['data'] ?? []);
            break;
        default:
            error_log("[NGT-n8n] Unhandled event: {$payload['event']}");
            return new WP_REST_Response(['status' => 'ignored', 'event' => $payload['event']], 200);
    }

    // 5. Log successful receipt
    error_log("[NGT-n8n] Webhook processed: {$payload['event']}");
    return new WP_REST_Response(['status' => 'success', 'received_at' => current_time('mysql')], 200);
}

/**
 * AI_AGENT: Sync payment data from n8n (idempotent)
 */
function ngt_sync_payment_from_n8n($data) {
    global $wpdb;
    $order_id = intval($data['order_id'] ?? 0);
    if (!$order_id) return;

    // Check if already processed
    if (get_post_meta($order_id, '_ngt_n8n_synced', true)) return;

    // Update order meta
    update_post_meta($order_id, '_ngt_n8n_synced', true);
    update_post_meta($order_id, '_ngt_n8n_synced_at', current_time('mysql'));

    // Trigger FluentCRM update if contact exists
    if (class_exists('FluentCRM\App\Models\Contact')) {
        $customer_id = intval($data['customer_id'] ?? 0);
        if ($customer_id) {
            $user = get_userdata($customer_id);
            if ($user) {
                $contact = \FluentCRM\App\Models\Contact::where('email', $user->user_email)->first();
                if ($contact) {
                    $contact->attachTags(['payment-verified']);
                    $contact->custom_fields['last_payment_date'] = current_time('mysql');
                    $contact->save();
                }
            }
        }
    }
}

