/**
 * AI_AGENT: Calculate tutor earnings for a session
 * Formula: (rate × 0.85) - penalties + bonuses
 */
function ngt_calculate_and_record_earnings($session_id, $tutor_id) {
    global $wpdb;

    // Get session details
    $session = get_post($session_id);
    if (!$session) return;

    $rate = floatval(get_post_meta($session_id, '_ngt_session_rate', true) ?: 400);
    $gross = $rate;
    $platform_fee = $gross * NGT_PLATFORM_FEE;

    // Calculate penalties
    $penalties = 0;
    $attendance = get_post_meta($session_id, '_ngt_attendance_tutor', true);
    if ($attendance === 'absent') {
        $penalties += $gross * 0.5; // 50% penalty for no-show
    }

    // Calculate bonuses
    $bonuses = 0;
    $tutor_rating = floatval(get_user_meta($tutor_id, '_ngt_average_rating', true) ?: 0);
    if ($tutor_rating >= NGT_TOP_RATING_THRESHOLD) {
        $bonuses += $gross * 0.05; // 5% bonus for top-rated tutors
    }

    $net = $gross - $platform_fee - $penalties + $bonuses;

    // Record in earnings table
    $wpdb->insert($wpdb->prefix . 'ngt_earnings', [
        'tutor_id' => $tutor_id,
        'session_id' => $session_id,
        'amount' => $gross,
        'platform_fee' => $platform_fee,
        'penalties' => $penalties,
        'bonuses' => $bonuses,
        'net_amount' => $net,
        'status' => 'pending',
        'created_at' => current_time('mysql'),
        'updated_at' => current_time('mysql')
    ], ['%d', '%d', '%f', '%f', '%f', '%f', '%f', '%s', '%s', '%s']);

    // Update tutor meta
    $current_earnings = floatval(get_user_meta($tutor_id, '_ngt_total_earned', true) ?: 0);
    update_user_meta($tutor_id, '_ngt_total_earned', $current_earnings + $net);

    return $net;
}

