/**
 * Creates custom tables on theme activation.
 */
function ngt_create_tables() {
    global $wpdb;
    $charset_collate = $wpdb->get_charset_collate();
    $tables = [];

    $tables['ngt_earnings'] = "CREATE TABLE {$wpdb->prefix}ngt_earnings (
        id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
        tutor_id BIGINT UNSIGNED NOT NULL,
        session_id BIGINT UNSIGNED NOT NULL,
        amount DECIMAL(10,2) NOT NULL,
        platform_fee DECIMAL(10,2) NOT NULL,
        penalties DECIMAL(10,2) DEFAULT 0,
        bonuses DECIMAL(10,2) DEFAULT 0,
        net_amount DECIMAL(10,2) NOT NULL,
        status ENUM('pending','completed','disputed','paid') DEFAULT 'pending',
        created_at DATETIME NOT NULL,
        updated_at DATETIME NOT NULL,
        FOREIGN KEY (tutor_id) REFERENCES {$wpdb->users}(ID) ON DELETE CASCADE,
        INDEX idx_tutor_month (tutor_id, created_at),
        INDEX idx_status (status)
    ) $charset_collate;";

    $tables['ngt_ratings'] = "CREATE TABLE {$wpdb->prefix}ngt_ratings (
        id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
        rater_id BIGINT UNSIGNED NOT NULL,
        rater_type ENUM('student','tutor','admin') NOT NULL,
        target_id BIGINT UNSIGNED NOT NULL,
        session_id BIGINT UNSIGNED NOT NULL,
        rating TINYINT UNSIGNED NOT NULL CHECK (rating BETWEEN 1 AND 5),
        comment TEXT,
        created_at DATETIME NOT NULL,
        updated_at DATETIME NOT NULL,
        FOREIGN KEY (rater_id) REFERENCES {$wpdb->users}(ID) ON DELETE CASCADE,
        FOREIGN KEY (target_id) REFERENCES {$wpdb->users}(ID) ON DELETE CASCADE,
        UNIQUE KEY unique_session_rater (rater_id, session_id, rater_type),
        INDEX idx_target_rating (target_id, rating)
    ) $charset_collate;";

    $tables['ngt_payouts'] = "CREATE TABLE {$wpdb->prefix}ngt_payouts (
        id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
        tutor_id BIGINT UNSIGNED NOT NULL,
        payout_date DATE NOT NULL,
        amount DECIMAL(10,2) NOT NULL,
        status ENUM('pending','processing','completed','failed') DEFAULT 'pending',
        bank_account_hash VARCHAR(255) NOT NULL,
        reference VARCHAR(100) UNIQUE,
        notes TEXT,
        created_at DATETIME NOT NULL,
        updated_at DATETIME NOT NULL,
        FOREIGN KEY (tutor_id) REFERENCES {$wpdb->users}(ID) ON DELETE CASCADE,
        UNIQUE KEY unique_tutor_month (tutor_id, payout_date),
        INDEX idx_status_date (status, payout_date)
    ) $charset_collate;";

    $tables['ngt_referrals'] = "CREATE TABLE {$wpdb->prefix}ngt_referrals (
        id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
        referrer_id BIGINT UNSIGNED NOT NULL,
        referred_user_id BIGINT UNSIGNED DEFAULT NULL,
        referral_code VARCHAR(50) UNIQUE NOT NULL,
        reward_amount DECIMAL(10,2) DEFAULT 50.00,
        reward_status ENUM('pending','completed','expired') DEFAULT 'pending',
        created_at DATETIME NOT NULL,
        updated_at DATETIME NOT NULL,
        FOREIGN KEY (referrer_id) REFERENCES {$wpdb->users}(ID) ON DELETE CASCADE,
        INDEX idx_code (referral_code),
        INDEX idx_status (reward_status)
    ) $charset_collate;";

    $tables['ngt_session_logs'] = "CREATE TABLE {$wpdb->prefix}ngt_session_logs (
        id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
        session_id BIGINT UNSIGNED NOT NULL,
        tutor_id BIGINT UNSIGNED NOT NULL,
        student_id BIGINT UNSIGNED NOT NULL,
        status ENUM('scheduled','completed','no_show','cancelled','disputed') DEFAULT 'scheduled',
        notes TEXT,
        recording_url VARCHAR(512),
        materials_url VARCHAR(512),
        attendance_tutor ENUM('present','absent','late') DEFAULT 'present',
        attendance_student ENUM('present','absent','late') DEFAULT 'present',
        created_at DATETIME NOT NULL,
        updated_at DATETIME NOT NULL,
        FOREIGN KEY (session_id) REFERENCES {$wpdb->posts}(ID) ON DELETE CASCADE,
        FOREIGN KEY (tutor_id) REFERENCES {$wpdb->users}(ID) ON DELETE CASCADE,
        FOREIGN KEY (student_id) REFERENCES {$wpdb->users}(ID) ON DELETE CASCADE,
        INDEX idx_tutor_status (tutor_id, status),
        INDEX idx_student_date (student_id, created_at)
    ) $charset_collate;";

    $tables['ngt_api_tokens'] = "CREATE TABLE {$wpdb->prefix}ngt_api_tokens (
        id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
        user_id BIGINT UNSIGNED NOT NULL,
        token_hash VARCHAR(255) NOT NULL,
        expires_at DATETIME NOT NULL,
        last_used DATETIME DEFAULT NULL,
        created_at DATETIME NOT NULL,
        FOREIGN KEY (user_id) REFERENCES {$wpdb->users}(ID) ON DELETE CASCADE,
        INDEX idx_token (token_hash),
        INDEX idx_user_expiry (user_id, expires_at)
    ) $charset_collate;";

    require_once(ABSPATH . 'wp-admin/includes/upgrade.php');
    foreach ($tables as $table_name => $sql) {
        dbDelta($sql);
    }
    return array_map(fn($t) => $wpdb->prefix . $t, array_keys($tables));
}

