// ============================================================================

function ngt_api_get_dashboard(WP_REST_Request $request) {
    $user = ngt_require_auth($request);
    if (is_wp_error($user)) return $user;

    $role = ngt_get_user_role($user->ID);
    switch ($role) {
        case 'tutor': return ngt_get_tutor_dashboard($user->ID);
        case 'parent': case 'student': return ngt_get_student_dashboard($user->ID);
        case 'admin': case 'support': return ngt_get_admin_dashboard($user->ID);
        default: return new WP_Error('unsupported_role', 'Dashboard not available for this role', ['status' => 403]);
    }
}

function ngt_get_tutor_dashboard($user_id) {
    global $wpdb;
    $month = date('Y-m');
    $earnings = $wpdb->get_row($wpdb->prepare(
        "SELECT SUM(net_amount) as total, COUNT(*) as sessions 
         FROM {$wpdb->prefix}ngt_earnings 
         WHERE tutor_id = %d AND status != 'disputed' 
         AND DATE_FORMAT(created_at, '%Y-%m') = %s",
        $user_id, $month
    ), ARRAY_A);

    $avg_rating = floatval(get_user_meta($user_id, '_ngt_average_rating', true) ?: 0);
    $review_count = intval($wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM {$wpdb->prefix}ngt_ratings 
         WHERE target_id = %d AND rater_type = 'student'",
        $user_id
    )));

    return [
        'role' => 'tutor',
        'earnings_month' => floatval($earnings['total'] ?? 0),
        'sessions_completed' => intval($earnings['sessions'] ?? 0),
        'average_rating' => $avg_rating,
        'review_count' => $review_count,
        'upcoming_sessions' => [], // Pull from Amelia API if needed
        'badges' => ngt_get_user_badges($user_id),
        'payout_next' => ngt_get_next_payout_date(),
        'profile_completion' => ngt_calculate_profile_completion($user_id, 'tutor')
    ];
}

function ngt_get_student_dashboard($user_id) {
    global $wpdb;
    $balance = floatval(get_user_meta($user_id, '_ngt_account_balance', true) ?: 0);
    $sessions_count = intval($wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM {$wpdb->prefix}ngt_session_logs WHERE student_id = %d",
