function ngt_api_create_session(WP_REST_Request $request) {
    $user = ngt_require_auth($request);
    if (is_wp_error($user)) return $user;

    $params = $request->get_json_params();
    $tutor_id = absint($params['tutor_id'] ?? 0);
    $student_id = absint($params['student_id'] ?? 0);
    $date = sanitize_text_field($params['date'] ?? '');
    $duration = absint($params['duration'] ?? 60);
    $subject = sanitize_text_field($params['subject'] ?? '');
    $rate = floatval($params['rate'] ?? 400);

    if (!$tutor_id || !$student_id || empty($date)) {
        return new WP_Error('invalid_params', 'Missing required fields', ['status' => 400]);
    }

    global $wpdb;
    $wpdb->insert($wpdb->prefix . 'ngt_session_logs', [
        'tutor_id' => $tutor_id, 'student_id' => $student_id, 'date' => $date,
        'duration' => $duration, 'subject' => $subject, 'rate' => $rate,
        'status' => 'scheduled', 'created_at' => current_time('mysql'),
        'updated_at' => current_time('mysql')
    ]);

    // Trigger Amelia booking & WooCommerce order via AutomatorWP
    if (function_exists('automatorwp_trigger_event')) {
        automatorwp_trigger_event([
            'trigger' => 'ngt_session_created',
            'tutor_id' => $tutor_id,
            'student_id' => $student_id,
            'session_id' => $wpdb->insert_id
        ]);
    }

    return [
        'id' => $wpdb->insert_id,
        'status' => 'scheduled',
        'zoom_link' => 'https://zoom.us/j/' . wp_generate_password(10, false), // Placeholder for real Zoom API
        'calendar_invite' => 'https://cal.nextgentutors.co.za/invite/' . $wpdb->insert_id
    ];
}

function ngt_api_get_session(WP_REST_Request $request) {
    $user = ngt_require_auth($request);
    if (is_wp_error($user)) return $user;

    $session_id = absint($request->get_param('id'));
    global $wpdb;
    $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ngt_session_logs WHERE id = %d", $session_id));

    if (!$row) return new WP_Error('not_found', 'Session not found', ['status' => 404]);
    if ($row->tutor_id !== $user->ID && $row->student_id !== $user->ID && !ngt_user_has_permission($user->ID, 'view_all_reports')) {
        return new WP_Error('forbidden', 'Access denied', ['status' => 403]);
    }

    return (array) $row;
}

function ngt_api_complete_session(WP_REST_Request $request) {
    $user = ngt_require_auth($request, 'mark_session_complete');
    if (is_wp_error($user)) return $user;

    $session_id = absint($request->get_param('id'));
    $params = $request->get_json_params();

    global $wpdb;
    $wpdb->update($wpdb->prefix . 'ngt_session_logs', [
        'status' => 'completed',
        'notes' => sanitize_textarea_field($params['notes'] ?? ''),
        'recording_url' => esc_url_raw($params['recording_url'] ?? ''),
        'materials_url' => esc_url_raw($params['materials_url'] ?? ''),
        'attendance_tutor' => in_array($params['attendance'] ?? '', ['present','absent','late']) ? $params['attendance'] : 'present',
        'updated_at' => current_time('mysql')
    ], ['id' => $session_id], ['%s','%s','%s','%s','%s','%s'], ['%d']);

    $session = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ngt_session_logs WHERE id = %d", $session_id));
    $earnings = ngt_calculate_and_record_earnings($session_id, $session->tutor_id);

    return [
        'status' => 'completed',
        'earnings_recorded' => true,
        'amount' => $earnings,
        'updated_at' => current_time('mysql')
    ];
}

function ngt_api_get_tutor_earnings(WP_REST_Request $request) {
    $user = ngt_require_auth($request);
    if (is_wp_error($user)) return $user;

    $tutor_id = absint($request->get_param('tutor_id'));
    $month = sanitize_text_field($request->get_param('month') ?? date('Y-m'));

    global $wpdb;
    $total = $wpdb->get_var($wpdb->prepare(
        "SELECT SUM(net_amount) FROM {$wpdb->prefix}ngt_earnings 
         WHERE tutor_id = %d AND status != 'disputed' 
         AND DATE_FORMAT(created_at, '%%Y-%%m') = %s",
        $tutor_id, $month
    ));

    $records = $wpdb->get_results($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ngt_earnings 
         WHERE tutor_id = %d AND DATE_FORMAT(created_at, '%%Y-%%m') = %s 
         ORDER BY created_at DESC",
        $tutor_id, $month
    ));

    return [
        'period' => $month,
        'gross_earnings' => floatval($total) / 0.85, // Reverse platform fee
        'platform_fee' => (floatval($total) / 0.85) * 0.15,
        'net_earnings' => floatval($total),
        'sessions' => $records
    ];
}

function ngt_api_process_payouts(WP_REST_Request $request) {
    $user = ngt_require_auth($request, 'process_payouts');
    if (is_wp_error($user)) return $user;

    $params = $request->get_json_params();
    $month = sanitize_text_field($params['month'] ?? date('Y-m'));
    $tutors = array_map('absint', $params['tutors'] ?? []);

    global $wpdb;
    $processed = 0;
    $total_amount = 0;

    foreach ($tutors as $tutor_id) {
        $earnings = $wpdb->get_var($wpdb->prepare(
            "SELECT SUM(net_amount) FROM {$wpdb->prefix}ngt_earnings 
             WHERE tutor_id = %d AND status = 'pending' 
             AND DATE_FORMAT(created_at, '%%Y-%%m') = %s",
            $tutor_id, $month
        ));

        if (!$earnings || floatval($earnings) < NGT_MIN_PAYOUT) continue;

        $bank_hash = ngt_encrypt_data(get_user_meta($tutor_id, '_ngt_bank_account', true));
        $reference = 'NGT-' . date('Ym') . '-' . str_pad($tutor_id, 5, '0', STR_PAD_LEFT);

        $wpdb->insert($wpdb->prefix . 'ngt_payouts', [
            'tutor_id' => $tutor_id, 'payout_date' => date('Y-m-d'),
            'amount' => floatval($earnings), 'status' => 'processing',
            'bank_account_hash' => $bank_hash, 'reference' => $reference,
            'created_at' => current_time('mysql'), 'updated_at' => current_time('mysql')
        ]);

        $wpdb->update($wpdb->prefix . 'ngt_earnings',
            ['status' => 'completed'], ['tutor_id' => $tutor_id, 'status' => 'pending']
        );

        $processed++;
        $total_amount += floatval($earnings);
    }

    ngt_trigger_n8n_webhook('payout.processed', [
        'count' => $processed, 'total_amount' => $total_amount, 'month' => $month
    ]);

    return [
        'status' => 'processing',
        'count' => $processed,
        'total_amount' => $total_amount,
        'reference' => 'BATCH-' . str_replace('-', '', date('Y-m-d'))
    ];
}

