## 📜 Complete Setup Script: `setup-ngt-platform.php`

```php
#!/usr/bin/env php
<?php
/**
 * NextGen Tutors - Platform Setup & Verification Script
 * Run via WP-CLI: wp eval-file setup-ngt-platform.php [--dry-run] [--force]
 * 
 * Features:
 * ✅ Auto-detects required plugins & themes
 * ✅ Creates SmartHead child theme if missing
 * ✅ Configures Amelia, Fluent Forms, FluentCRM, WooCommerce, MasterStudy, AutomatorWP
 * ✅ Generates pages with correct shortcodes
 * ✅ Seeds RBAC demo data (2 users/role)
 * ✅ Runs verification & outputs status report
 * ✅ Supports rollback & safe abort
 */

if (!defined('WP_CLI') || !WP_CLI) {
    WP_CLI::error('This script must be run via WP-CLI. Usage: wp eval-file setup-ngt-platform.php');
    exit(1);
}

$dry_run = WP_CLI\Utils\get_flag_value(WP_CLI::get_arguments(), '--dry-run', false);
$force   = WP_CLI\Utils\get_flag_value(WP_CLI::get_arguments(), '--force', false);

if ($dry_run) WP_CLI::line("🔍 DRY RUN MODE - No changes will be saved.\n");

// ============================================================================
// 1. PRE-FLIGHT CHECKS
// ============================================================================
WP_CLI::log('🔍 Checking prerequisites...');
$required_plugins = [
    'ameliabooking/ameliabooking.php'   => ['class' => 'AmeliaBooking\\AmeliaBooking'],
    'fluent-forms/fluent-forms.php'     => ['class' => 'FluentForm\\FormBuilder\\FluentForm'],
    'fluent-crm/fluent-crm.php'         => ['class' => 'FluentCRM\\App\\App'],
    'woocommerce/woocommerce.php'       => ['class' => 'WooCommerce'],
    'masterstudy-lms/lms.php'           => ['class' => 'STM_LMS'],
    'automatorwp/automatorwp.php'       => ['class' => 'AutomatorWP\\Core'],
];

$missing = [];
foreach ($required_plugins as $file => $checks) {
    $active = is_plugin_active($file);
    $exists = class_exists($checks['class']) || function_exists('ngt_plugin_loaded_' . str_replace('/', '_', $file));

    if (!$active || !$exists) {
        $missing[] = $file;
    }
}

if (!empty($missing)) {
    WP_CLI::warning("⚠️ Missing or inactive plugins detected:");
    foreach ($missing as $p) WP_CLI::warning("   - $p");
    WP_CLI::line("\n🛑 Integration paused. Activate plugins and re-run, or add --force to bypass (not recommended).");
    exit(1);
}

// Check SmartHead theme
$parent_theme = wp_get_theme()->get('Template') ?: wp_get_theme()->get('Name');
if (stripos($parent_theme, 'smarthead') === false && !$force) {
    WP_CLI::error("❌ SmartHead theme not detected. Activate it first or use --force.");
    exit(1);
}
WP_CLI::success("✅ All prerequisites met.");

// ============================================================================
// 2. CHILD THEME CREATION
// ============================================================================
WP_CLI::log("\n🎨 Setting up child theme...");
$child_dir = get_theme_root() . '/nextgen-tutors';
$child_style = $child_dir . '/style.css';
$child_func = $child_dir . '/functions.php';

if (!file_exists($child_dir) || $force) {
    wp_mkdir_p($child_dir);
    wp_mkdir_p($child_dir . '/inc');
