function ngt_run_verification() {
    global $wpdb;
    $checks = [
        'Child Theme Active'        => (wp_get_theme()->get_template()==='nextgen-tutors'),
        'Custom Tables Created'     => $wpdb->get_var("SHOW TABLES LIKE '{$wpdb->prefix}ngt_earnings'")===$wpdb->prefix.'ngt_earnings',
        'Pages Generated'           => count(get_posts(['post_type'=>'page','numberposts'=>-1])) >= 10,
        'WC Products Created'       => count(wc_get_products(['limit'=>-1])) >= 4,
        'FluentCRM Segments'        => class_exists('FluentCRM\App\Models\ContactList') && \FluentCRM\App\Models\ContactList::count() >= 4,
        'RBAC Users Seeded'         => count_users()['total_users'] >= 8,
        'Relational Data Exists'    => $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ngt_session_logs") > 0 && $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ngt_ratings") > 0,
        'API Endpoint Live'         => wp_remote_get(home_url('/wp-json/ngt/v1/'))['response']['code']===200
    ];

    $table = [['Component', 'Status', 'Verify Link']];
    foreach ($checks as $name => $result) {
        $status = $result ? '✅ PASS' : '❌ FAIL';
        $link = $result ? 'Verified' : 'Review Required';
        $table[] = [$name, $status, $link];
    }
    WP_CLI\Utils\format_items('table', $table, ['Component', 'Status', 'Verify Link']);

    $failed = array_filter($checks, fn($r)=>!$r);
    if (!empty($failed)) {
        WP_CLI::warning("\n⚠️ " . count($failed) . " checks failed. Run: wp eval-file setup-ngt-platform.php --force");
    } else {
        WP_CLI::success("\n🎉 ALL CHECKS PASSED. Platform ready for production testing.");
        WP_CLI::line("\n📊 Demo Credentials:");
        WP_CLI::line("   Parent: parent1@nextgentutors.co.za / Demo@2026!");
