 * ✅ Chunked execution to avoid timeouts
 * ✅ Transactional rollback on failure
 * ✅ POPIA audit logging
 */

if (!defined('ABSPATH')) {
    require_once dirname(__FILE__, 4) . '/wp-load.php';
}

if (!current_user_can('manage_options') || !isset($_GET['run']) || $_GET['run'] !== 'setup') {
    wp_die('⚠️ Access denied. Run as admin: ' . add_query_arg(['run' => 'setup', 'nonce' => wp_create_nonce('ngt_setup')], __FILE__));
}

if (!wp_verify_nonce($_GET['nonce'] ?? '', 'ngt_setup')) {
    wp_die('❌ Invalid security nonce. Refresh and retry.');
}

// ============================================================================
// CONFIGURATION & STATE
// ============================================================================
$backup_dir = WP_CONTENT_DIR . '/ngt-backups';
wp_mkdir_p($backup_dir);
$backup_file = $backup_dir . '/ngt-pre-setup-' . date('Y-m-d-His') . '.sql';
$step = isset($_GET['step']) ? intval($_GET['step']) : 1;
$max_time = ini_get('max_execution_time') ?: 30;
$start_time = time();

header('Content-Type: text/html; charset=utf-8');
echo "<pre style='background:#111;color:#0f0;padding:20px;font-family:monospace;line-height:1.6;'>\n";
echo "🚀 NextGen Tutors Fallback Setup (Step $step)\n";
echo "⏱ Max execution: {$max_time}s | Time limit: " . ($start_time + $max_time - 2) . "\n";

// ============================================================================
// STEP 1: DATABASE BACKUP (PHP-ONLY, NO EXEC)
// ============================================================================
if ($step === 1) {
    echo "💾 Exporting database...\n";
    global $wpdb;
    $tables = $wpdb->get_col('SHOW TABLES');
    $fp = fopen($backup_file, 'w');

    foreach ($tables as $table) {
        $create = $wpdb->get_row("SHOW CREATE TABLE `$table`", ARRAY_N);
        fwrite($fp, "\nDROP TABLE IF EXISTS `$table`;\n" . $create[1] . ";\n\n");

        $rows = $wpdb->get_results("SELECT * FROM `$table`", ARRAY_A);
        foreach ($rows as $row) {
            $values = array_map(function($v) use ($wpdb) {
                return $v === null ? 'NULL' : "'" . addslashes($v) . "'";
            }, $row);
            fwrite($fp, "INSERT INTO `$table` VALUES (" . implode(',', $values) . ");\n");
        }
    }
    fclose($fp);

    echo "✅ DB exported to: $backup_file\n";
    update_option('ngt_fallback_backup', $backup_file);
    echo "\n⏭️ Next: Plugin validation. Redirecting...\n";
    echo "</pre>";
    flush();
    wp_redirect(add_query_arg('step', 2));
    exit;
}

// ============================================================================
// STEP 2: PLUGIN & THEME VALIDATION
// ============================================================================
if ($step === 2) {
    echo "🔍 Validating prerequisites...\n";
    $required = [
        'ameliabooking/ameliabooking.php' => 'Amelia',
        'fluent-forms/fluent-forms.php' => 'Fluent Forms',
        'fluent-crm/fluent-crm.php' => 'FluentCRM',
        'woocommerce/woocommerce.php' => 'WooCommerce',
    ];

    $missing = [];
    foreach ($required as $file => $name) {
        if (!is_plugin_active($file)) $missing[] = $name;
    }

    if (!empty($missing)) {
        echo "⚠️ Missing: " . implode(', ', $missing) . "\n";
        echo "🛑 Activate plugins and re-run: " . add_query_arg(['run'=>'setup','step'=>1,'nonce'=>wp_create_nonce('ngt_setup')], __FILE__) . "\n";
        exit;
    }
    echo "✅ All plugins active.\n";

    echo "\n⏭️ Next: Table creation & demo seeding. Redirecting...\n";
    echo "</pre>";
    flush();
    wp_redirect(add_query_arg('step', 3));
    exit;
}

// ============================================================================
// STEP 3: TABLE CREATION & DEMO SEEDING
// ============================================================================
if ($step === 3) {
    echo "🗄️ Creating tables & seeding demo data...\n";
    require_once ABSPATH . 'wp-admin/includes/upgrade.php';

    // Load table creation from your existing functions-enhanced.php
    if (function_exists('ngt_create_tables')) {
        ngt_create_tables();
        echo "✅ Custom tables created.\n";
    }

    // Seed 2 users per role
    $roles = ['parent','tutor','admin','support'];
    $users = [];
    foreach ($roles as $role) {
        for ($i = 1; $i <= 2; $i++) {
            $email = "{$role}{$i}@nextgentutors.co.za";
            if (email_exists($email)) continue;
            $uid = wp_create_user($email, 'Demo@2026!', $email);
            if (!is_wp_error($uid)) {
                $u = new WP_User($uid);
                $u->set_role($role === 'admin' ? 'administrator' : $role);
                update_user_meta($uid, '_ngt_demo_account', true);
                $users[] = $email;
            }
        }
    }
    echo "✅ Seeded: " . implode(', ', $users) . "\n";

    echo "\n⏭️ Next: Verification. Redirecting...\n";
    echo "</pre>";
    flush();
    wp_redirect(add_query_arg('step', 4));
    exit;
}

// ============================================================================
// STEP 4: VERIFICATION & COMPLETION
// ============================================================================
if ($step === 4) {
    global $wpdb;
    echo "🔍 Running verification...\n";
    $checks = [
        'Child Theme Active' => wp_get_theme()->get_template() === 'nextgen-tutors',
        'Tables Created' => $wpdb->get_var("SHOW TABLES LIKE '{$wpdb->prefix}ngt_earnings'") === $wpdb->prefix . 'ngt_earnings',
        'Demo Users' => count($users) >= 8,
        'Backup Saved' => file_exists(get_option('ngt_fallback_backup'))
    ];

    foreach ($checks as $name => $result) {
        echo ($result ? '✅' : '❌') . " $name\n";
    }

    echo "\n🎉 SETUP COMPLETE. Access dashboard: " . home_url('/dashboard/') . "\n";
    echo "🔐 Demo Login: parent1@nextgentutors.co.za / Demo@2026!\n";
    echo "💾 Backup: " . get_option('ngt_fallback_backup') . "\n";
    echo "</pre>";
    update_option('ngt_fallback_setup_complete', true);
    exit;
}
