## 🛠️ Programmatic Tag Assignment (PHP)
*Add to `functions-enhanced.php` for real-time sync:*
```php
/**
 * FluentCRM Tag Mapper
 * Assigns tags based on custom field thresholds & workflow rules
 */
function ngt_sync_fluentcrm_tags($contact_id) {
    if (!class_exists('FluentCRM\App\Models\Contact')) return;

    $contact = \FluentCRM\App\Models\Contact::find($contact_id);
    if (!$contact) return;

    $fields = $contact->custom_fields;
    $current_tags = array_map('strtolower', $contact->tags->pluck('title')->toArray());

    // Parent/Student Rules
    if ($contact->email && filter_var($contact->email, FILTER_VALIDATE_EMAIL)) {
        $sessions = intval($fields['cf_sessions_count'] ?? 0);
        $rating = floatval($fields['cf_latest_rating'] ?? 5.0);
        $last_session = $fields['cf_last_session_date'] ?? null;
        $consent = filter_var($fields['cf_popia_consent_given'], FILTER_VALIDATE_BOOLEAN);

        if ($sessions >= 5 && !in_array('quick learner', $current_tags)) {
            $contact->attachTags(['Quick Learner']);
        }
        if ($sessions >= 10 && $consent && !in_array('loyal customer', $current_tags)) {
            $contact->attachTags(['Loyal Customer']);
        }
        if ($last_session && strtotime($last_session) < strtotime('-60 days') && !in_array('inactive', $current_tags)) {
            $contact->attachTags(['Inactive']);
        }
    }

    // Tutor Rules
    if (($contact->contact_type ?? '') === 'tutor') {
        $status = $fields['cf_verification_status'] ?? 'pending';
        $avg_rating = floatval($fields['cf_avg_rating'] ?? 0);
        $reviews = intval($fields['cf_review_count'] ?? 0);
        $cancellations = intval($fields['cf_cancellations_month'] ?? 0);

        if ($status === 'approved' && !in_array('verified tutor', $current_tags)) {
            $contact->attachTags(['Verified Tutor']);
            $contact->removeFromLists(['Tutor Applicants']);
            $contact->addToLists(['Verified Tutors']);
        }
        if ($avg_rating >= 4.8 && $reviews >= 50 && !in_array('top rated', $current_tags)) {
            $contact->attachTags(['Top Rated']);
        }
        if ($cancellations > 3 && !in_array('unreliable', $current_tags)) {
            $contact->attachTags(['Unreliable']);
        }
    }

    $contact->save();
}
add_action('fluentcrm_contact_updated', 'ngt_sync_fluentcrm_tags');
```

