    ['label' => 'Average Rating', 'slug' => 'cf_avg_rating', 'type' => 'number'],
    ['label' => 'Review Count', 'slug' => 'cf_review_count', 'type' => 'number'],
    ['label' => 'Total Earnings', 'slug' => 'cf_total_earned', 'type' => 'number'],
    ['label' => 'Payout Rate', 'slug' => 'cf_payout_rate', 'type' => 'number'],

    // POPIA Compliance Fields
    ['label' => 'POPIA Consent Given', 'slug' => 'cf_popia_consent_given', 'type' => 'checkbox'],
